#!/usr/bin/env node
/**
 * App icon sheet for the phone home screen (drawn in icons.mjs).
 *
 *   icons.png       one sheet, 28x28 tiles, 8 per row
 *   icons.meta.ts   generated tile positions for the app (do not edit)
 *
 * Usage:
 *   node scripts/sprites/build-icons.mjs                    # writes src/assets/sprites/icons.*
 *   node scripts/sprites/build-icons.mjs --out some/dir     # custom output dir
 *   node scripts/sprites/build-icons.mjs --preview out.png  # also writes an enlarged contact sheet
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Bmp, encodePNG, rgba, scaleNearest } from './lib.mjs';
import { buildIcons } from './icons.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const argVal = (name) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : undefined;
};
const OUT_DIR = path.resolve(argVal('--out') ?? path.join(here, '../../src/assets/sprites'));
const PREVIEW = argVal('--preview');

const { sheet, sprites, tile } = buildIcons();
const png = encodePNG(sheet);
const BUDGET = 6 * 1024;
if (png.length > BUDGET) throw new Error(`icons.png: ${png.length} B is over its ${BUDGET} B budget`);

const meta = `/* AUTO-GENERATED by scripts/sprites/build-icons.mjs from scripts/sprites/icons.mjs – do not edit. */
/** App icons (icons.png): ${tile}x${tile} tiles, shown at 2x (56 px) on the phone home screen. */
export const ICON_SHEET = { w: ${sheet.w}, h: ${sheet.h}, tile: ${tile} } as const;
export const ICONS = {
${sprites.map((s) => `  ${s.key}: { x: ${s.x}, y: ${s.y} },`).join('\n')}
} as const;
export type IconName = keyof typeof ICONS;
`;

fs.mkdirSync(OUT_DIR, { recursive: true });
fs.writeFileSync(path.join(OUT_DIR, 'icons.png'), png);
fs.writeFileSync(path.join(OUT_DIR, 'icons.meta.ts'), meta);
console.log(`wrote ${path.relative(process.cwd(), OUT_DIR) || '.'}: icons.png ${sheet.w}x${sheet.h} (${sprites.length} icons), ${png.length} B`);

if (PREVIEW) {
  const K = 4;
  const pad = 8;
  const perRow = 6;
  const rows = Math.ceil(sprites.length / perRow);
  const cell = tile * K + pad;
  const out = new Bmp(perRow * cell + pad, rows * cell + pad);
  out.fill(rgba('#1e1b4b'));
  sprites.forEach((s, i) => {
    const one = new Bmp(tile, tile);
    for (let y = 0; y < tile; y++)
      for (let x = 0; x < tile; x++) {
        const o = ((s.y + y) * sheet.w + (s.x + x)) * 4;
        if (sheet.px[o + 3]) one.set(x, y, sheet.px.slice(o, o + 4));
      }
    out.paste(scaleNearest(one, K), pad + (i % perRow) * cell, pad + Math.floor(i / perRow) * cell);
  });
  fs.writeFileSync(PREVIEW, encodePNG(out));
  console.log('preview ->', PREVIEW);
}
